func processURLs(urls <-chan string) <-chan string {
	out := make(chan string)
	if urls == nil {
		close(out)
		return out
	}

	var wg sync.WaitGroup
	for url := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			resp, err := http.Get(url)
			if err != nil || resp == nil {
				out <- fmt.Sprintf("%s - not ok", url)
				return
			}
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				out <- fmt.Sprintf("%s - ok", url)
			} else {
				out <- fmt.Sprintf("%s - not ok", url)
			}
		}()
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

