package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	in := make(chan string)
	handle(context.Background(), 7*time.Second, in, 7)

	for i := 0; i < 10; i++ {
		in <- fmt.Sprintf("in-%0.2v", i)
		time.Sleep(200 * time.Millisecond)
	}

	fmt.Printf("done sending in.")
	select {
	case <-time.After(3 * time.Second):
		fmt.Printf("exiting.")
		break
	}
}

func handle(ctx context.Context, tickerDur time.Duration, in <-chan string, batchSize int) {
	go func() {
		msg := make(chan string)
		ticker := time.NewTicker(tickerDur)
		defer close(msg)
		defer ticker.Stop()

		go func(msg chan string) {
			for {
				s := <-in
				msg <- s
			}
		}(msg)

		batch := make([]string, 0, batchSize)
		for {
			select {
			case <-ticker.C:
				if len(batch) == 0 {
					continue
				}
			case m := <-msg:
				batch = append(batch, m)
				if len(batch) <= batchSize {
					continue
				}
			case <-ctx.Done():
				fmt.Printf("context done.\n")
				break
			}

			for _, m := range batch {
				fmt.Printf("processing %s\n", m)
			}
			batch = batch[:0]
		}
	}()
}

