		jobs:       make(chan Job, bufferSize),
		processing: make(map[int]bool),
	}
}

func (p *JobProcessor) StartWorkers(n int) {
	for i := 0; i < n; i++ {
		go func(workerID int) {
			for job := range p.jobs {
				p.mu.Lock()
				if p.processing[job.ID] {
					p.mu.Unlock()
					log.Printf("worker %d: job %d already processing", workerID, job.ID)
					continue
				}
				p.processing[job.ID] = true
				p.mu.Unlock()

				log.Printf("worker %d: started job %d", workerID, job.ID)
				time.Sleep(100 * time.Millisecond) // simulate work
				log.Printf("worker %d: finished job %d", workerID, job.ID)

				p.mu.Lock()
				delete(p.processing, job.ID)
				p.mu.Unlock()
			}
		}(i)
	}
}

func (p *JobProcessor) Submit(job Job) {
	p.jobs <- job
}

func (p *JobProcessor) Stop() {
	close(p.jobs)
}

