func (bs *BasketServer) AddItemAndOrder(ctx context.Context, req *AddItemRequest) (*EmptyResponse, error) {
	// Load the user's basket
	basket, err := bs.repo.Load(ctx, req.UserID)
	if err != nil {
		return nil, err
	}

	// If the basket is already ordered, no changes are allowed
	if basket.Status == "ordered" {
		return nil, fmt.Errorf("basket is already ordered and cannot be modified")
	}

	// Flag to decide whether a new item needs to be added
	found := false

	// Iterate over all basket items
	for i, item := range basket.Items {
		// Check whether an item with the same ProductID already exists
		if item.ProductID == req.ProductID {
			// If found, update its quantity and price
			basket.Items[i].Count += req.Count
			basket.Items[i].Price = req.Price

			found = true
			break
		}
	}

	// If the item is new, add it to the basket
	if !found {
		basket.Items = append(basket.Items, BasketItem{
			BasketID:  basket.ID,
			ProductID: req.ProductID,
			Count:     req.Count,
			Price:     req.Price,
		})
	}

	// Recalculate the basket total
	var total uint64 = 0
	for _, item := range basket.Items {
		total += item.Count * item.Price
	}
	basket.Total = total

	// If the request implies checking out the basket
	if req.Count == 0 {
		basket.Status = "ordered"
		// Send a message to the broker
		if err := bs.producer.SendMessage(ctx, *basket); err != nil {
			return nil, fmt.Errorf("error notifying broker: %w", err)
		}
	}

	// Save the basket
	if err := bs.repo.Save(ctx, basket); err != nil {
		return nil, err
	}

	return &EmptyResponse{}, nil
}

