package main

import (
	"fmt"
	"sync"
)

type Account struct {
	id        int
	amount    int
	suspended bool
}

func (account *Account) Inc(amount int) {
	account.amount += amount
}

func (account *Account) Dec(amount int) {
	account.amount -= amount
}

func (account *Account) SetSuspended(isSuspended bool) {
	account.suspended = isSuspended
}

func (account *Account) IsSuspended() bool {
	return account.suspended
}

// =====================================================================

const numberOfTransactions = 100

func main() {
	waitchannel := make(chan bool, numberOfTransactions*2)

	var a = Account{id: 1, amount: 1000, suspended: false}
	var b = Account{id: 2, amount: 1000, suspended: false}

	transactionsStartSignal := sync.WaitGroup{}
	transactionsStartSignal.Add(numberOfTransactions * 2)

	transferRoutine := func(sourceAccount *Account, destinationAccount *Account, amount int) {
		transactionsStartSignal.Done()
		transactionsStartSignal.Wait()

		if !sourceAccount.IsSuspended() && !destinationAccount.IsSuspended() {
			sourceAccount.Dec(amount)
			destinationAccount.Inc(amount)
		}

		waitchannel <- true
	}

	for i := 0; i < numberOfTransactions; i++ {
		go transferRoutine(&a, &b, 10)
		go transferRoutine(&b, &a, 10)
	}

	for i := 0; i < numberOfTransactions*2; i++ {
		<-waitchannel
	}

	fmt.Println(a.amount, b.amount)
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type WaitGroup struct {
	mu sync.RWMutex
}

func (w *WaitGroup) Go(f func()) {
	go func() {
		w.mu.RLock()
		f()
		w.mu.RUnlock()
	}()
}

func (w *WaitGroup) Wait() {
	w.mu.Lock()
	w.mu.Unlock()
}

func main() {
	var wg WaitGroup
	var done atomic.Int32
	for i := 0; i < 5; i++ {
		wg.Go(func() {
			time.Sleep(100 * time.Millisecond)
			done.Add(1)
		})
	}
	wg.Wait()
	fmt.Println("finished:", done.Load())
}

a:
Output varies from run to run, for example:

```text
finished: 2
finished: 0
finished: 1
finished: 0
finished: 0
```

(five separate runs; `5` is expected.)

The bug: `RLock` is taken **inside** the spawned goroutine. `Wait()` often runs before those goroutines are scheduled, so `Lock()` succeeds immediately and `Wait` returns while the work hasn't even started. Same bug class as calling `wg.Add(1)` inside the goroutine.

Fix: take the read lock synchronously in `Go`, before `go`:

```go
func (w *WaitGroup) Go(f func()) {
	w.mu.RLock()
	go func() {
		defer w.mu.RUnlock()
		f()
	}()
}
```

Caveats: once `Wait` is waiting, a new `Go` call blocks (a pending writer blocks new readers), and it's `RWMutex` abuse. Still a nice trick.

Without WaitGroup: a counter under a mutex plus a channel closed at zero.

```go
type Group struct {
	mu   sync.Mutex
	n    int
	done chan struct{}
}

func (g *Group) Go(f func()) {
	g.mu.Lock()
	if g.n == 0 {
		g.done = make(chan struct{})
	}
	g.n++
	g.mu.Unlock()
	go func() {
		defer func() {
			g.mu.Lock()
			g.n--
			if g.n == 0 {
				close(g.done)
			}
			g.mu.Unlock()
		}()
		f()
	}()
}

func (g *Group) Wait() {
	g.mu.Lock()
	if g.n == 0 {
		g.mu.Unlock()
		return
	}
	done := g.done
	g.mu.Unlock()
	<-done
}
```

For a known count, you can also collect `n` values from a channel (`for range n { <-doneCh }`).

code:
func delay(duration time.Duration, fn func()) func() {
	canceled := false

	go func() {
		time.Sleep(duration)
		if !canceled {
			fn()
		}
	}()

	return func() {
		canceled = true
	}
}

a:
The goroutine reads `canceled` and the cancel closure writes it with no synchronization: a data race (`-race` reports it), and the compiler is free to never observe the write.

Minimal fix: an atomic flag.

```go
func delay(duration time.Duration, fn func()) func() {
	var canceled atomic.Bool
	go func() {
		time.Sleep(duration)
		if !canceled.Load() {
			fn()
		}
	}()
	return func() { canceled.Store(true) }
}
```

Better: don't park a goroutine at all. `time.AfterFunc` does exactly this, and `Stop` tells you whether it prevented the call.

```go
func delay(d time.Duration, fn func()) (cancel func() bool) {
	return time.AfterFunc(d, fn).Stop
}
```

Semantics to mention: with the flag version, cancel racing with the check can still let `fn` start just after cancel returns (check-then-act). If the caller must know, return a bool as `Timer.Stop` does, or guard check+run with a mutex. A `context`-based variant (`select` on `time.After` and `ctx.Done()`) also works and releases the goroutine early on cancel.

Simplest correct version: a CAS spinlock on `atomic.Bool` that yields the processor while contended.

```go
type Mutex struct {
	state atomic.Bool
}

func (m *Mutex) Lock() {
	for !m.state.CompareAndSwap(false, true) {
		runtime.Gosched()
	}
}

func (m *Mutex) Unlock() {
	if !m.state.CompareAndSwap(true, false) {
		panic("unlock of unlocked mutex")
	}
}
```

Atomics in Go are sequentially consistent, so a successful CAS in `Lock` observes everything written before the previous `Unlock`: the needed happens-before.

Alternative with no busy waiting: a channel with capacity 1.

```go
type ChanMutex chan struct{}

func NewChanMutex() ChanMutex { return make(ChanMutex, 1) }
func (m ChanMutex) Lock()     { m <- struct{}{} }
func (m ChanMutex) Unlock()   { <-m }
```

Waiters are parked by the runtime, and you get `TryLock`/timeouts for free via `select`.

What the real `sync.Mutex` adds: brief spinning, then parking on a runtime semaphore instead of burning CPU; a waiter counter; starvation mode (FIFO hand-off after 1 ms of waiting). A spinlock is fine only for tiny critical sections; under contention it wastes CPU and is unfair.

